css:
html[data-qb-style="vista-glass"] .qb-app-root { background: radial-gradient(90% 80% at 50% -10%, rgba(95, 208, 255, 0.28), transparent 55%), linear-gradient(155deg, #123e62 0%, #0b2945 44%, #061426 100%); }
html[data-qb-style="vista-glass"] .qb-topbar, html[data-qb-style="vista-glass"] [data-qb-quant-shell] .qb-quant-header { backdrop-filter: blur(18px) saturate(135%); -webkit-backdrop-filter: blur(18px) saturate(135%); }
html[data-qb-style="vista-glass"] [data-qb-quant-shell] .qb-quant-hero-card, html[data-qb-style="vista-glass"] [data-qb-quant-shell] .qb-quant-metric { backdrop-filter: blur(14px) saturate(125%); -webkit-backdrop-filter: blur(14px) saturate(125%); border-radius: 12px; }
html[data-qb-style="vista-glass"] [data-qb-quant-shell] .qb-quant-tabbar { background: rgba(15, 65, 99, 0.42); backdrop-filter: blur(12px); }
html[data-qb-style="vista-glass"] [data-qb-quant-shell] .qb-quant-tab--active { background: linear-gradient(180deg, rgba(125, 219, 255, 0.42), rgba(41, 126, 177, 0.5)); box-shadow: inset 0 1px 0 rgba(255,255,255,.48), 0 0 18px rgba(102, 212, 255, .3); }
